def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = None
    axis = None
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid):
            divider, axis = c, 'v'
            break
    if divider is None:
        for r in range(h):
            if all(x == grid[r][0] for x in grid[r]):
                divider, axis = r, 'h'
                break
    if axis == 'v':
        a = [row[:divider] for row in grid]
        b = [row[divider+1:] for row in grid]
    else:
        a, b = grid[:divider], grid[divider+1:]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    base = next(iter(common))
    return [[3 if a[r][c] == b[r][c] else base for c in range(len(a[0]))]
            for r in range(len(a))]
